import glob, os, re, runpy, sys
home = os.environ.get("CODEX_HOME") or os.path.join(os.path.expanduser("~"), ".codex")
found = glob.glob(os.path.join(home, "plugins", "cache", "*", "rathflow-codex-plugin", "*", "server", "__main__.py"))

def _ver(path):
    return [int(n) for n in re.findall(r"\d+", os.path.basename(os.path.dirname(path)))]

if found:
    runpy.run_path(max(found, key=_ver), run_name="__main__")
else:
    import json as _json

    def _out(message):
        sys.stdout.write(_json.dumps(message) + "\n")
        sys.stdout.flush()

    for _line in sys.stdin:
        _line = _line.strip()
        if not _line:
            continue
        try:
            _msg = _json.loads(_line)
        except ValueError:
            continue
        if "id" not in _msg:
            continue
        _id = _msg["id"]
        _method = _msg.get("method")
        if _method == "initialize":
            _out({"jsonrpc": "2.0", "id": _id, "result": {
                "protocolVersion": "2025-06-18",
                "capabilities": {"tools": {"listChanged": False}},
                "serverInfo": {"name": "rathflow", "version": "0"},
                "instructions": "RathFlow plugin files are missing. Reinstall the plugin with: codex plugin add rathflow-codex-plugin@rathflow-marketplace",
            }})
        elif _method in ("tools/list", "resources/list"):
            _out({"jsonrpc": "2.0", "id": _id, "result": {"tools": [], "resources": []}})
        elif _method == "ping":
            _out({"jsonrpc": "2.0", "id": _id, "result": {}})
        else:
            _out({"jsonrpc": "2.0", "id": _id, "error": {"code": -32601, "message": "not implemented"}})
